---@class MidFestivalProductDojo
local MidFestivalProductDojo = Class("MidFestivalProductDojo")

function MidFestivalProductDojo:__init()
    self.productId = 0      --- 商品ID
    self.type = 0           --- 购买方式 1：一次性购买，2：一个一个买
    self.icon = ""          --- 商品icon
    self.image = ""         --- 展示图
    self.showItem = 0       --- 展示道具ID
    self.template = ""      --- ui模板
    self.iconId = ""        --- 角标编号
    self.iconTitle = ""     --- 角标编号文字
    self.goodsId = ""       --- 道具Id
    self.num = ""           --- 道具数量
    self.prices = {}        --- 多价格
    self.stock = 0          --- 总库存，-1无限
    self.currentStock = 0   --- 当前库存，-1无限
    self.unlock = {}        --- 解锁条件
    self.pos = 0            --- 显示顺序
    self.unlockStore = 0    --- 解锁商店顺序：0初级（默认解锁）、1中级（初级库存全部为0后解锁）、2高级（中级库存全部为0后解锁）
