---Update
---更新数据
---@param jsonData table
function MidFestivalProductDojo:Fill(jsonData)
    jsonData = checkTable(jsonData)
    for key, value in pairs(jsonData) do
        --只更新自己关心的数据
        if isSet(jsonData, key) and table.haskey(self, key) then
            if key == "prices" then
                for k, v in pairs(value) do
                    local p = {}
                    p.current = v.current
                    p.original = v.original
                    p.currency = tonumber(k)
                    table.insert(self.prices, p)
                end
            else
                self[key] = value
            end
        end
    end
end

function MidFestivalProductDojo:SortPrices(weight)
    if next(self.prices) == nil then
        return
    end

    if #self.prices == 1 then
        return
    end

    --print(table.dump(self.prices))
    table.sort(self.prices, function(a, b)
        return weight[a.currency] < weight[b.currency]
    end)
end

return MidFestivalProductDojo